#ifndef MONTAGE_IO_CMS_BUILTIN_H
#define MONTAGE_IO_CMS_BUILTIN_H

// M22 色彩管理内核 · 内置 profile。全部由公开色度定义（基色、白点、传递函数）程序生成，
// 专用至公有领域（CC0-1.0）——嵌入这些 profile 的文档无许可义务。
// 翻译自 photocraft crates/cms/src/builtin.rs（MIT OR Apache-2.0）。

#include "io/cms/profile.h"

namespace montage {
namespace cms {

// 每个内置 profile 的版权标签文本。
inline constexpr const char* kBuiltinCopyright =
    "No copyright: CC0-1.0 public domain dedication. Generated by Montage (photocraft-derived).";

// 内置 profile 标识。
enum class Builtin : uint8_t {
    Srgb,            // sRGB IEC 61966-2.1（Rec. 709 基色、D65、sRGB 传递函数）
    DisplayP3,       // Display P3（DCI-P3 基色、D65、sRGB 传递函数）
    AdobeRgbCompat,  // Adobe RGB (1998) 兼容：公开基色、D65、gamma 563/256
    ProPhotoCompat,  // ProPhoto 兼容：ROMM RGB 基色、D50、gamma 1.8
    LinearSrgb,      // sRGB 基色 + 线性传递函数
    Rec2020,         // Rec. 2020 基色、D65、Rec. 709 传递函数
    GrayGamma22,     // 灰、gamma 2.2
    SGray,           // sRGB 传递函数的灰（灰 v = sRGB (v,v,v)）
    LabD50,          // CIE L*a*b* D50 恒等（设备 Lab = PCS Lab，ICC v4 编码）
    CoatedCmyk,      // 合成涂布纸 CMYK（300% TAC、中 GCR）
};

// 稳定标识（命令/设置用）。
const char* builtinId(Builtin b);
// profile 描述（desc 标签）。
const char* builtinDescription(Builtin b);
// 按 id 查（大小写不敏感；接受别名与描述文本）。
std::optional<Builtin> builtinFromId(const std::string& s);

// 内置 profile（进程内单次构建；声明序 = 枚举序）。
const Profile& builtinProfile(Builtin b);

// 颜色空间的默认 profile：sRGB / sGray / 合成 CMYK / Lab D50。
const Profile* defaultProfileFor(ColorSpace cs);

inline const Profile& builtinSrgb() { return builtinProfile(Builtin::Srgb); }

// 线性灰（灰度 OpenEXR 持有的形态）：只赋给此类文件，不作工作空间。
const Profile& builtinLinearGray();

}  // namespace cms
}  // namespace montage

#endif  // MONTAGE_IO_CMS_BUILTIN_H
